import pandas as pd
# Check 5.9× from exp011
df = pd.read_csv('exp011_causal_forest.csv')
print('Columns:', list(df.columns))
# Find max ratio of global/naive bias
for k in df['K'].unique():
    for regime in df[df['K']==k]['regime'].unique():
        d = df[(df['K']==k) & (df['regime']==regime)]
        for sg in d['subgroup'].unique():
            for z in d['z_level'].unique():
                naive = d[(d['subgroup']==sg) & (d['z_level']==z) & (d['method']=='naive_forest')]
                glob = d[(d['subgroup']==sg) & (d['z_level']==z) & (d['method']=='global_forest')]
                echte = d[(d['subgroup']==sg) & (d['z_level']==z) & (d['method']=='ec_hte_forest')]
                if len(naive)>0 and len(glob)>0:
                    nb = abs(naive['bias'].values[0])
                    gb = abs(glob['bias'].values[0])
                    if nb > 0:
                        ratio = gb/nb
                        if ratio > 2:
                            print(f'K={k} {regime} sg={sg} z={z}: naive={nb:.4f} global={gb:.4f} ratio={ratio:.2f}')
"
